  `isBuy` int NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_kygui_timkiem`(`tab` ASC, `isBuy` ASC, `item_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 762 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

